const e={model:"gemma4:12b",digest:"4eb23ef187e2c5462566d6a1d3bbbc2f1346d0b4327cbb66d58fffbcc9b2b05c",promptVersion:3,date:"2026-08-30",status:{"ni.character.awareness.why":"reviewed","ni.character.control.why":"reviewed","ni.character.endurance.why":"reviewed","ni.character.precision.why":"reviewed","ni.character.speed.why":"reviewed","ni.energy.recovery.auxiliary":"reviewed","ni.energy.recovery.dominant":"reviewed","ni.energy.recovery.inferior":"reviewed","ni.energy.recovery.shadow":"reviewed","ni.energy.recovery.tertiary":"reviewed","ni.feeder.fe":"reviewed","ni.feeder.fi":"reviewed","ni.feeder.se":"reviewed","ni.feeder.te":"reviewed","ni.feeder.ti":"reviewed","ni.fieldNotes.mirror":"reviewed","ni.fieldNotes.vignette.brainstorm":"reviewed","ni.fieldNotes.vignette.cantJustKnow":"reviewed","ni.fieldNotes.vignette.grip":"reviewed","ni.fieldNotes.vignette.loop":"reviewed","ni.fieldNotes.vignette.mechanicsHunch":"reviewed","ni.fieldNotes.vignette.meeting":"reviewed","ni.fieldNotes.vignette.mistakenForSi":"reviewed","ni.hero.heading":"reviewed","ni.hero.subtitle":"reviewed","ni.hero.tag":"reviewed","ni.lab.btn.aha.label":"reviewed","ni.lab.btn.aha.sub":"reviewed","ni.lab.btn.cassandra.label":"reviewed","ni.lab.btn.cassandra.sub":"reviewed","ni.lab.btn.flash.label":"reviewed","ni.lab.btn.flash.sub":"reviewed","ni.lab.btn.focus.label":"reviewed","ni.lab.btn.focus.sub":"reviewed","ni.lab.btn.overfit.label":"reviewed","ni.lab.btn.overfit.sub":"reviewed","ni.lab.meter.pleasure":"reviewed","ni.lab.meter.stress":"reviewed","ni.lab.narration.aha":"reviewed","ni.lab.narration.aha2":"reviewed","ni.lab.narration.cassandra":"reviewed","ni.lab.narration.cassandra2":"reviewed","ni.lab.narration.flash":"reviewed","ni.lab.narration.flash2":"reviewed","ni.lab.narration.focus":"reviewed","ni.lab.narration.focus2":"reviewed","ni.lab.narration.hover":"reviewed","ni.lab.narration.intro":"reviewed","ni.lab.narration.introHintCoarse":"reviewed","ni.lab.narration.introHintFine":"reviewed","ni.lab.narration.overfit":"reviewed","ni.lab.narration.overfit2":"reviewed","ni.lab.state.cynical":"reviewed","ni.lab.state.equilibrium":"reviewed","ni.lab.state.euphoric":"reviewed","ni.lab.state.freeze":"reviewed","ni.lab.state.overfit":"reviewed","ni.lab.telemetry.cogState":"reviewed","ni.lab.telemetry.conf":"reviewed","ni.lab.telemetry.loss":"reviewed","ni.meta.title":"reviewed","ni.slot.auxiliary":"reviewed","ni.slot.critical":"reviewed","ni.slot.demon":"reviewed","ni.slot.dominant":"reviewed","ni.slot.inferior":"reviewed","ni.slot.opposing":"reviewed","ni.slot.tertiary":"reviewed","ni.slot.trickster":"reviewed","ni.zoneA.canvasAria":"reviewed","ni.zoneB.heading":"reviewed","ni.zoneB.lede":"reviewed","ni.zoneB.railAria":"reviewed","ni.zoneC.heading":"reviewed","ni.zoneC.lede":"reviewed","ni.zoneC.unstableDefault":"reviewed","ni.zoneD.canvasAria":"reviewed","ni.zoneD.heading":"reviewed","ni.zoneD.kicker":"reviewed","ni.zoneD.lede":"reviewed","ni.zoneD.ledeHintCoarse":"reviewed","ni.zoneD.ledeHintFine":"reviewed","ni.zoneE.lede":"reviewed"}},a={_meta:e,"ni.character.awareness.why":"segura de su forma, incapaz de mostrar su trabajo","ni.character.control.why":"las revelaciones llegan a su propio ritmo; el timón responde lentamente","ni.character.endurance.why":"la convergencia es paciente — el embudo funciona durante horas sin esfuerzo","ni.character.precision.why":"una trayectoria, ajustada al límite; la envolvente se estrecha a medida que avanza","ni.character.speed.why":"la convergencia espera a que encaje — la visión llega completa y tarde","ni.energy.recovery.auxiliary":"Recuperación limpia una vez que la lectura ha sido entregada a alguien.","ni.energy.recovery.dominant":"Se rellena parcialmente durante el uso: cada visión que se asienta aporta un poco de retorno.","ni.energy.recovery.inferior":"La repisa de la resaca: ~30 min en los que todo el sistema funciona con poca intensidad y la lectura del desastre sigue repitiéndose.","ni.energy.recovery.shadow":"Incompleto — parte de la carga simplemente no regresa hoy.","ni.energy.recovery.tertiary":"Más lento: la búsqueda de patrones tiene que dejarse de lado primero.","ni.feeder.fe":{figure:"Muchos canales suaves alimentando una única línea de paciente.",mechanism:"Fe — sentimiento extravertido — devuelve el estado de la sala: qué está pasando entre estas personas en particular y qué es probable que hagan con ello. Más canales, entradas más pequeñas, una imagen sobre trayectorias de relación. La corrección llega socialmente — más lenta que un número, y más difícil de descartar.",pair:"la pareja INFJ · ENFJ",provenance:"myers"},"ni.feeder.fi":{figure:"La línea se oscurece sin moverse.",mechanism:"El bucle INTJ, con Te fuera: Fi — sentimiento introvertido — suministra el juicio, también desde dentro, sopesando la imagen frente a lo que importa a una persona y nada más. Sin aire y autoconfirmatorio: una lectura de cómo todo esto sucede que se vuelve más segura cuanto más tiempo nadie fuera lo toque, y no más precisa.",pair:"el bucle Ni–Fi del INTJ",provenance:"community",warn:"Acoplamiento de bucle: juicio introvertido alimentando percepción introvertida — sin corrección desde el exterior."},"ni.feeder.se":{figure:"Los fragmentos llegan más rápido de lo que pueden retenerse; la imagen casi se forma y se escapa.",mechanism:"Se — percepción extravertida — inunda la entrada con el presente: denso, concreto, inmediato, todo es real y nada va a ninguna parte, mientras nada lo clasifica — ambas funciones recogen y ninguna juzga. Estas dos también se sitúan en el mismo eje: lo que una toma como obvio, la otra lo trata como ruido. Las pilas reales alternan percibir y juzgar precisamente por esta razón.",pair:"Percepción alimentando a percepción",provenance:"myers",warn:"Acoplamiento inestable: percepción alimentadora de percepción, sin nada que juzgue a ninguna de las dos."},"ni.feeder.te":{figure:"Un flujo delgado y dirigido; la envolvente se estrecha donde aterrizan los números.",mechanism:"Te — pensamiento extravertido — devuelve resultados, mediciones y el estado del plan: pocos aportes, cada uno difícil, cada uno en un canal estrecho y dirigido. La imagen que se forma es sobre cómo una estructura se mueve a lo largo de los años, y se corrige cuando los números no coinciden. La corrección de errores más directa que tiene Ni, y la más fiable.",pair:"la pareja INTJ · ENTJ",provenance:"myers"},"ni.feeder.ti":{figure:"El límite sella un giro más; observa con qué frecuencia el encaje se activa antes en este estado.",mechanism:"El bucle INFJ, con Fe fuera: Ti — pensamiento introvertido — aporta juicio, pero desde dentro. La imagen se comprueba por coherencia interna y nunca contra nada en la habitación, así que la convergencia es más rápida y la certeza más estrecha — y lo único que corrige la imagen es la misma cabeza que la produjo.",pair:"el bucle Ni–Ti del INFJ",provenance:"community",warn:"Acoplamiento de bucle: juicio introvertido alimentando percepción introvertida — sin corrección desde el exterior."},"ni.fieldNotes.mirror":{figure:"Dos embudos, boca con boca.",mechanismHtml:"Mismo elemento, actitud opuesta — y la diferencia es hacia dónde apunta el embudo. <strong>Ne</strong> toma una entrada y la expande en muchos futuros, todos vivos a la vez, todos baratos de mantener, ninguno de ellos elegido. <strong>Ni</strong> toma muchas entradas y las canaliza en una, y esa llega entera, cara de cambiar, e imposible de mostrar. Ne cambia compromiso por rango; Ni cambia rango por una convicción que no puede obtener.",provenance:"jung"},"ni.fieldNotes.vignette.brainstorm":{figure:"Un embudo no puede funcionar como un aspersor.",kind:"el instrumento incorrecto",mechanism:"Pida a Ni veinte opciones rápidas y observe cómo la herramienta rechaza la especificación: permanecerá en silencio durante la ráfaga de notas adhesivas y finalmente ofrecerá una opción, tarde, totalmente formada, con el argumento para ella soldado. La convergencia que la hace valiosa es exactamente lo que la hace incorrecta aquí. Los equipos que saben esto dejan de calificar a Ni por volumen y empiezan a entregarle la lista corta en su lugar.",provenance:"community",title:"Lluvia de ideas"},"ni.fieldNotes.vignette.cantJustKnow":{figure:"Un instrumento que no puede imprimir sus datos brutos.",kind:"la acusación",mechanism:"La acusación trata una derivación ausente como una base ausente. Lo que realmente falta es una interfaz: el embudo consumió cientos de observaciones y devolvió solo el destino, y los pasos intermedios nunca se almacenaron en ningún lugar recuperable. La respuesta correcta a una lectura de Ni no es ni la fe ni el descarte: es tratarla como una medición de un instrumento que no puede mostrar su trabajo, y probarla como cualquier otra medición.",provenance:"currents",title:"No puedes saberlo sin más"},"ni.fieldNotes.vignette.grip":{figure:"El horizonte se ajusta a la distancia de un brazo.",kind:"la garra",mechanism:"Un INTJ que agota sus reservas deja de ver hacia dónde va todo y se sumerge en la inferior Se — comprando cosas, conduciendo demasiado rápido, comiendo y bebiendo sin darse cuenta, forzando el cuerpo hasta que es lo único en la habitación. No es un cambio de personalidad: un asiento de baja capacidad recibiendo una inundación de tamaño dominante.",provenance:"quenk",title:"La garra"},"ni.fieldNotes.vignette.loop":{figure:"Sellado, elaborado, certero.",kind:"el bucle",mechanism:"Bajo estrés, la Ni dominante de un INFJ se empareja con la Ti terciaria; ambas miran hacia adentro, con el contacto de Fe con personas reales cortado entre ellas. La lectura se vuelve más elaborada, internamente consistente y más segura, y nadie fuera de esa cabeza la ha tocado en semanas. Este patrón de misma dirección se llama bucle.",provenance:"community",title:"El bucle"},"ni.fieldNotes.vignette.mechanicsHunch":{figure:"Previsión de banda estrecha, manos callosas.",kind:"como terciaria",mechanism:'Ni terciaria en un ISTP o ISFP: un motor de convergencia silencioso bajo un exterior práctico. Surge como el mecánico que se detiene a mitad del trabajo porque el fallo "no va a ser el alternador", el escalador que cambia de ruta por una razón que llega como certeza antes de que llegue como clima. Previsión de banda estrecha y cercana al cuerpo — confiable en máquinas y terreno, y rara vez invitada a opinar sobre cualquier otra cosa.',provenance:"grant",title:"La corazonada del mecánico"},"ni.fieldNotes.vignette.meeting":{figure:"El embudo solo devolvió el destino.",kind:"avistamiento de campo",mechanism:"A diez minutos, alguien con Ni dominante sabe cómo termina el proyecto y lo dice. Al preguntar por qué, ofrecen una razón que es verdadera pero no es la razón; es lo más cercano que se puede decir a una lectura que nunca tuvo pasos. Seis meses después resulta que tenían razón, lo cual no mejora en nada la siguiente explicación.",provenance:"community",title:"La Reunión"},"ni.fieldNotes.vignette.mistakenForSi":{figure:"El registro frente al vector.",kind:"malinterpretado",mechanism:'Ambas son silenciosas, cuidadosas e interiores, por lo que los dos perceptores introvertidos se colapsan —normalmente como "personas de los detalles". La pista es lo que recupera "¿cómo lo sabes?". Si produce el registro: la fecha, el precedente, las últimas tres veces que ocurrió exactamente esto. Ni produce la forma: hacia dónde se dirige esto, despojado de cada particular que construyó la trayectoria. Una archiva el pasado a resolución completa; la otra lo comprime más allá de la recuperación.',provenance:"community",title:"Confundido con Si"},"ni.hero.heading":"La convergencia de {fn}","ni.hero.subtitle":"Un campo de observaciones dispersas, una trayectoria ajustada a través de ellas — y una única construcción que recorre la línea a través del tiempo, ya segura de dónde se curva.","ni.hero.tag":"intuición introvertida","ni.lab.btn.aha.label":"¡Aha! Síntesis","ni.lab.btn.aha.sub":"inyectar datos dispares → sintetizar paradigma","ni.lab.btn.cassandra.label":"Tragedia de Cassandra","ni.lab.btn.cassandra.sub":"pronóstico ignorado → ocurre fallo previsto","ni.lab.btn.flash.label":"Interrupción Táctica Flash","ni.lab.btn.flash.sub":"¡haz la llamada ahora!","ni.lab.btn.focus.label":"Simulación de Enfoque Profundo","ni.lab.btn.focus.sub":"entra en un bloque de concentración profunda sin interrupciones","ni.lab.btn.overfit.label":"Exceso de micromanagement","ni.lab.btn.overfit.sub":"forzar formato de hoja de cálculo granular","ni.lab.meter.pleasure":"Placer","ni.lab.meter.stress":"Estrés","ni.lab.narration.aha":{figure:"Los residuos colapsan y la envolvente de varianza se contrae.",mechanism:"Dos docenas de observaciones sin relación entre sí —y por un momento no lo tienen—. Entonces, una trayectoria hace la afirmación de cada valor atípico a la vez, y lo que era una nube es de repente una línea con una dirección. Note el orden de los eventos: la respuesta llegó, y luego fue obvia.",provenance:"currents"},"ni.lab.narration.aha2":{figure:"R² cercano a la unidad, pérdida cercana a cero, el estrés ha desaparecido.",mechanism:"Este es el pago por el que Ni trabaja —no elogios, ni resultados: compresión. Veinte cosas se convirtieron en una sola, y esa única cosa predice. Las anomalías que la produjeron ya son indistinguibles de la línea a la que se unieron.",provenance:"currents"},"ni.lab.narration.cassandra":{figure:"Observa cómo el constructo llega al cruce que nombró de antemano.",mechanism:"El modelo vio esto. La lectura ha atravesado el límite de fallo durante algún tiempo, y decirlo en voz alta no cambió nada.",provenance:"currents"},"ni.lab.narration.cassandra2":{figure:"La lectura de confianza nunca se movió.",mechanism:"Fallo, según lo previsto. El ajuste fue preciso todo el tiempo —lo que es la crueldad específica aquí: tener razón pronto es indistinguible, desde fuera, de estar equivocado hasta que deja de serlo. El pequeño y amargo ascenso en el medidor de placer es real, y no es una sensación agradable.",provenance:"currents"},"ni.lab.narration.flash":{figure:"La trayectoria se fragmenta en ruido de alta frecuencia mientras el tiempo presente bombardea el visor.",mechanism:'"Haz la llamada ahora". El único recurso en el que esta función se ejecuta —tiempo para simular— es el que acaba de ser revocado. No tiene una respuesta rápida; tiene una respuesta en búfer, y el búfer ha recibido la orden de detenerse.',provenance:"currents"},"ni.lab.narration.flash2":{figure:"La línea se ensambla de nuevo desde un ajuste inferior.",mechanism:"La descarga pasa y el reajuste comienza desde un R² derribado. No se aprendió nada durante la interrupción; el tiempo bajo fuego no es dato, es solo tiempo. Lo que una fecha límite compra de Ni no es velocidad — es cualquier conjetura que estuviera por ahí cuando el reloj marcó cero.",provenance:"currents"},"ni.lab.narration.focus":{figure:"La trayectoria se extiende suavemente más allá del borde del visor.",mechanism:"La puerta se cierra y la entrada se detiene — no resuelta, solo ya no entra. La proyección se extiende: un paso más allá del ahora, y otro, con la incertidumbre apenas ensanchándose. Es la máquina haciendo lo que tiene precio, a la profundidad para la que tiene precio.",provenance:"currents"},"ni.lab.narration.focus2":{figure:"Mismos puntos, línea más larga.",mechanism:"Nota lo que el enfoque profundo no hizo: no añadió datos. La previsión se alargó sobre las mismas observaciones, porque la simulación ininterrumpida es cómo esta función convierte el material retenido en alcance. La mejora más barata que Ni recibe es una puerta cerrada.",provenance:"currents"},"ni.lab.narration.hover":"Tienes el timón. Izquierda es antes, derecha es después; y la composición del constructo en cada punto es lo que el modelo cree que el concepto luce allí. Observa que es el mismo objeto en todo el trayecto: desarrollo, no reemplazo.","ni.lab.narration.intro":"El motor funciona sin supervisión: las observaciones se acumulan, una trayectoria se ajusta a ellas y la construcción recorre la línea de un extremo del tiempo al otro, cambiando a medida que avanza.","ni.lab.narration.introHintCoarse":"Pulsa y arrastra de izquierda a derecha en la cámara para tomar el timón tú mismo — o perturba el motor de abajo y observa cómo responde la telemetría.","ni.lab.narration.introHintFine":"Pasa el cursor sobre la cámara para tomar el timón tú mismo o perturba el motor de abajo y observa cómo responde la telemetría.","ni.lab.narration.overfit":{figure:"La línea de tendencia pasa por cada punto de ruido individualmente; la lectura del horizonte marca cero pasos hacia adelante.",mechanism:"Cada celda formateada, cada oscilación local respetada. La precisión sobre lo que ya ocurrió es espectacular — y la extrapolación es basura: el modelo ha memorizado los residuos y olvidado la dirección.",provenance:"currents"},"ni.lab.narration.overfit2":{figure:"La construcción vibra para respetar los decimales.",mechanism:"Este es el coste que la microgestión impone a un instrumento de largo alcance: la generalidad. Obligada a dar cuenta de cada célula, ya no puede decir hacia dónde va nada —precisión sobre el presente, comprada con el futuro.",provenance:"currents"},"ni.lab.state.cynical":"Resignación cínica","ni.lab.state.equilibrium":"Equilibrio óptimo","ni.lab.state.euphoric":"Flujo eufórico","ni.lab.state.freeze":"Abrumación / Congelación","ni.lab.state.overfit":"Fatiga por sobreajuste","ni.lab.telemetry.cogState":"Estado cognitivo","ni.lab.telemetry.conf":"Confianza de predicción","ni.lab.telemetry.loss":"Pérdida del modelo","ni.meta.title":"Ni — Intuición Introvertida · CURRENTS","ni.slot.auxiliary":{example:"El plan de cinco años de un ENTJ contiene una frase de pura visión; el resto es ejecución.",figure:"Un embudo de cuatro quintos que alimenta una máquina que envía.",mechanism:"En el segundo asiento, la lectura larga sirve a algo ya en marcha: aporta dirección en lugar de identidad, y la función de juicio dominante la convierte en un plan o una sala gestionada. Más rápida de enunciar, más fácil de debatir y mucho menos probable que se quede en una sola imagen durante una década.",provenance:"myers"},"ni.slot.critical":{example:"Un INFP concluye a medianoche que el patrón de toda su vida es ahora visible, y no es bueno.",figure:"Una línea gris a través del yo, extendida hasta el horizonte.",mechanism:"En el sexto asiento, la previsión se vuelve hacia adentro y emite veredictos sobre la propia vida — esto es lo que eres, aquí es donde termina — total, sin fuente y dirigida a nadie más. Predice con mucha más confianza de lo que verifica.",provenance:"beebe"},"ni.slot.demon":{example:"Un ISFJ sabe, durante una tarde terrible, exactamente cómo se marchará cada persona que ama.",figure:"Una única línea, trazada en oscuro, que atraviesa todos los puntos a la vez.",mechanism:"El octavo asiento es el más raro y peor. Cuando hay una erupción, produce una certeza negra sobre cómo termina todo esto — aplicada a todo a la vez, inmune a la evidencia, e indiferente a que la versión de ayer dijera algo distinto. Es el asiento menos practicado en la pila, no una profecía.",provenance:"beebe"},"ni.slot.dominant":{example:"A diez minutos del inicio, un INFJ sabe cómo termina el proyecto — y tarda seis meses en demostrar que tiene razón.",figure:"CURRENTS representa esto como una regresión a máxima profundidad: una envolvente ajustada, un ajuste sin prisas.",mechanism:"En el primer asiento, todo se lee por hacia dónde va, y la lectura corre continuamente, invisiblemente, a bajo coste. Pasan largos tramos en los que no ocurre nada legible; entonces llega una respuesta completa, ya cierta. Mostrar los pasos es genuinamente difícil: los pasos nunca se mantuvieron por separado.",provenance:"myers"},"ni.slot.inferior":{example:"Un ESTP que nunca mira más allá de esta noche se despierta a las 4 a.m. seguro de que el negocio está condenado, en detalle.",figure:"Un embudo tenue que dispara rara vez, y siempre hacia el mismo punto oscuro.",mechanism:"En el cuarto asiento, el futuro llega como un veredicto en lugar de un pronóstico. Largos periodos de vivir en el presente son puntuados —bajo fatiga o estrés— por una certeza total repentina de que esto termina mal, siempre iba a terminar así y no es discutible, en un registro que no suena como ellos. Esta es la garra de Quenk.",provenance:"quenk"},"ni.slot.opposing":{example:"Dicho que el mercado solo va en una dirección, un ENFP narra instantáneamente el colapso — y luego pide el postre.",figure:"Bajo la línea de flotación, una contratrayectoria dibujada de un solo trazo y abandonada.",mechanism:"El quinto asiento abre la sombra — las cuatro posiciones que una persona ejecuta rara vez, y mayormente sin notarlo. Aquí la lectura larga despierta combativa: cuando la visión única del futuro de otra persona empieza a cerrar opciones, aparece una certeza rival — más oscura, más inevitable, y mantenida exactamente el tiempo suficiente para rechazar la primera.",provenance:"beebe"},"ni.slot.tertiary":{example:"El mecánico se detiene a mitad del trabajo: «no va a ser el alternador». Y no lo es.",figure:"Un embudo de tamaño medio que se enfoca y luego divaga.",mechanism:"En el asiento terciario, la lectura de patrones llega en ráfagas y se confía de forma desigual: un sentido repentino y claro de cómo se desarrolla una situación —normalmente sólido, ocasionalmente una historia completa construida sobre nada— con poco interés en defender cualquiera de las dos. Se estabiliza con la edad, principalmente aprendiendo qué intuiciones propias verificar.",provenance:"grant"},"ni.slot.trickster":{example:"Un ESTJ no detecta la carta de dimisión entre líneas y, en su lugar, encuentra una conspiración en el plan de asientos.",figure:"El sobre nunca se estrecha; el ajuste se asienta junto a los puntos.",mechanism:"En el séptimo asiento, la implicación es un juego amañado: o no hay nada entre líneas o todo lo es. El asiento alterna entre un subtexto ausente que estaba claramente ahí y la construcción de uno elaborado que nadie pretendía —sin malicia, y normalmente sin notar que lo hizo.",provenance:"beebe"},"ni.zoneA.canvasAria":"Representación visual interactiva de la Intuición Introvertida como un motor de regresión: observaciones dispersas convergen en una trayectoria ajustada con una envolvente de confianza, y una construcción sintetizada recorre la línea a través del tiempo, transformándose a medida que avanza. Haga clic o arrastre a través de la cámara para dirigir la construcción a lo largo del eje del tiempo.","ni.zoneB.heading":"Las ocho caras de Ni","ni.zoneB.lede":"El lienzo representa Ni como una regresión: muchas observaciones entran, una trayectoria ajustada sale. El lugar donde Ni se sitúa en la pila de una persona —el orden fijo en que aparecen sus ocho funciones— cambia el comportamiento de la lectura. Haz clic en una posición para ver el cambio, desde el embudo pausado de la dominante hasta la única certeza negra de la sombra, y observa la lectura de convergencia: cuenta la historia antes que el pie de foto. Desliza el control de madurez para ver cómo los asientos inferiores ganan fidelidad con la edad.","ni.zoneB.railAria":"Posiciones de la pila para Ni","ni.zoneC.heading":"¿Qué alimenta a Ni?","ni.zoneC.lede":"Ni reúne; no juzga. La percepción introvertida es alimentada por el juicio extravertido, por lo que sus verdaderos compañeros son los jueces externos: Te y Fe, las funciones que aportan corrección desde fuera. Haz clic en una alimentadora para ver qué converge.","ni.zoneC.unstableDefault":"Acoplamiento inestable: la percepción alimenta a la percepción, sin que nada juzgue a ninguna de las dos.","ni.zoneD.canvasAria":"El motor de regresión Ni: observaciones dispersas, una trayectoria ajustada con una envolvente de varianza y un constructo que puede dirigirse hacia adelante y hacia atrás a lo largo del eje del tiempo mediante puntero o arrastre","ni.zoneD.heading":"El motor de regresión","ni.zoneD.kicker":"Zona D · el motor de regresión","ni.zoneD.lede":"Ni ajusta una trayectoria predictiva a través de una entrada ruidosa y multidimensional, y luego la proyecta hacia adelante en el tiempo. Este laboratorio expone el estado en vivo del motor —estrés, placer, confianza, pérdida— y cinco formas en las que un día puede tratarlo. Activa un escenario y observa cómo la telemetría responde.","ni.zoneD.ledeHintCoarse":"Pulsa y arrastra hacia la izquierda o derecha en la cámara en cualquier momento para dirigir la construcción a través del tiempo tú mismo.","ni.zoneD.ledeHintFine":"Pasa el cursor sobre la cámara en cualquier momento para dirigir la construcción a través del tiempo tú mismo.","ni.zoneE.lede":"Patrones de la naturaleza: cómo Ni se manifiesta en la vida diaria."};export{e as _meta,a as default};
